let tape =
  Vhs.tape
    [
      Vhs.comment
        "Generated by tape.ml: a themed event history with one bounded live \
         region.";
      Vhs.require "dune";
      Vhs.output "ocaml-console/examples/matrix/matrix.gif";
      Vhs.blank ();
      Vhs.set (Shell "bash");
      Vhs.set (Font_size 18);
      Vhs.set (Width 1000);
      Vhs.set (Height 560);
      Vhs.set (Theme "Builtin Dark");
      Vhs.set (Padding 20);
      Vhs.set (Typing_speed (Ms 20));
      Vhs.blank ();
      Vhs.type' "opam exec -- dune exec ocaml-console/examples/matrix/main.exe";
      Vhs.enter ();
      Vhs.wait (Wait_screen "There is no spoon.");
      Vhs.sleep (S 2.);
    ]

let () = Fmt.pr "%a" Vhs.pp tape
